import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ShowProfile{XUID: "2535413830400711"}
XUID = bytes.fromhex("1032353335343133383330343030373131")

# generated by gophertunnel b8bd735:
# packet.ShowProfile{XUID: ""}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.ShowProfile{XUID: strings.Repeat("x", 200)}
LONG_XUID = bytes.fromhex("c801") + bytes.fromhex("78") * 200

GOLDENS = [
    pytest.param(v2225.ShowProfilePacket(player_xuid="2535413830400711"), XUID, id="xuid"),
    pytest.param(v2225.ShowProfilePacket(), EMPTY, id="empty"),
    pytest.param(v2225.ShowProfilePacket(player_xuid="x" * 200), LONG_XUID, id="long-xuid"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_show_profile_is_packet_104(version):
    assert version.packets[104] is version.ShowProfilePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_profile_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_profile_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
